import React, { useState } from 'react';
import { formStyles } from './shared/IntegrationFormStyles';

/**
 * OneDrive Integration Component
 */
export default function OneDrive({ settings, hasPro, isConnected, onConnect, setMessage, setShowDisconnectModal, setDisconnectIntegration }) {
  const [showAppSecret, setShowAppSecret] = useState(false);
  const siteUrl = window.location.origin + window.location.pathname;
  const defaultRedirectUri = siteUrl || settings.redirect_uri || window.location.origin;

  return (
    <>
      {/* Alias */}
      <div>
        <label htmlFor="title" style={formStyles.label}>Alias</label>
        <input
          type="text"
          id="title"
          name="title"
          defaultValue={settings.title || 'OneDrive'}
          disabled={!hasPro}
          style={{ ...formStyles.input, maxWidth: '500px' }}
        />
        <p style={formStyles.description}>Enter a title which will be displayed on File Manager</p>
      </div>

      {/* Application (client) ID */}
      <div>
        <label htmlFor="app_id" style={formStyles.label}>Application (client) ID</label>
        <input
          type="text"
          id="app_id"
          name="app_id"
          defaultValue={settings.app_id || ''}
          disabled={!hasPro}
          style={{ ...formStyles.input, maxWidth: '500px' }}
        />
        <p style={formStyles.description}>
          Enter your OneDrive Application (client) ID from your{' '}
          <a href="https://portal.azure.com/#view/Microsoft_AAD_RegisteredApps/ApplicationsListBlade" target="_blank" rel="noopener noreferrer" style={formStyles.link}>
            Azure AD app registration.
          </a>
        </p>
      </div>

      {/* Client secret */}
      <div>
        <label htmlFor="app_secret" style={formStyles.label}>Client secret</label>
        <div style={{ position: 'relative', maxWidth: '500px' }}>
          <input
            type={showAppSecret ? 'text' : 'password'}
            id="app_secret"
            name="app_secret"
            defaultValue={settings.app_secret || ''}
            disabled={!hasPro}
            style={{ ...formStyles.input, paddingRight: '40px' }}
          />
          <button
            type="button"
            onClick={() => setShowAppSecret(!showAppSecret)}
            disabled={!hasPro}
            style={{
              position: 'absolute',
              right: '10px',
              top: '50%',
              transform: 'translateY(-50%)',
              background: 'none',
              border: 'none',
              cursor: !hasPro ? 'not-allowed' : 'pointer',
              padding: '5px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#666',
              zIndex: 10,
              opacity: !hasPro ? 0.5 : 1,
            }}
            title={showAppSecret ? 'Hide App Secret' : 'Show App Secret'}
          >
            {showAppSecret ? (
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"></path>
                <line x1="1" y1="1" x2="23" y2="23"></line>
              </svg>
            ) : (
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                <circle cx="12" cy="12" r="3"></circle>
              </svg>
            )}
          </button>
        </div>
        <p style={formStyles.description}>
          Enter your OneDrive Client secret from your{' '}
          <a href="https://portal.azure.com/#view/Microsoft_AAD_RegisteredApps/ApplicationsListBlade" target="_blank" rel="noopener noreferrer" style={formStyles.link}>
            Azure AD app registration.
          </a>
        </p>
      </div>

      {/* Redirect URI (Read-only) */}
      <div>
        <label htmlFor="redirect_uri" style={formStyles.label}>Redirect URI</label>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', maxWidth: '500px' }}>
          <input
            type="text"
            id="redirect_uri"
            name="redirect_uri"
            value={defaultRedirectUri}
            readOnly
            disabled={!hasPro}
            style={{ ...formStyles.input, background: '#f5f5f5', cursor: 'not-allowed' }}
          />
          <button
            type="button"
            onClick={() => {
              navigator.clipboard.writeText(defaultRedirectUri).then(() => {
                if (setMessage) {
                  setMessage({ type: 'success', text: 'Redirect URI copied to clipboard!' });
                  setTimeout(() => setMessage(null), 2000);
                }
              });
            }}
            disabled={!hasPro}
            style={{
              background: 'transparent',
              border: '1px solid #ddd',
              borderRadius: '4px',
              padding: '10px 12px',
              cursor: !hasPro ? 'not-allowed' : 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              opacity: !hasPro ? 0.5 : 1
            }}
            title="Copy to clipboard"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <rect x="9" y="9" width="13" height="13" rx="2" ry="2" stroke="#666" />
              <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" stroke="#666" />
            </svg>
          </button>
        </div>
        <p style={formStyles.description}>
          Copy this URL and paste it in your Azure AD app registration under Redirect URIs
        </p>
      </div>

      {/* Private Folder Access */}
      <div>
        <label htmlFor="private_folder_access" style={formStyles.label}>Private Folder Access</label>
        <input
          type="text"
          id="private_folder_access"
          name="private_folder_access"
          defaultValue={settings.private_folder_access || ''}
          disabled={!hasPro}
          style={{ ...formStyles.input, maxWidth: '500px' }}
          placeholder="e.g. Documents"
        />
        <p style={formStyles.description}>
          Enter a folder name/path to restrict access to that folder only. Leave blank to use the root directory.
        </p>
      </div>

      {/* Connect/Disconnect Button */}
      <div style={{ marginTop: '20px' }}>
        {!isConnected ? (
          <button
            type="button"
            onClick={onConnect}
            disabled={!hasPro || !settings.app_id || !settings.app_secret}
            style={{
              ...formStyles.installButton,
              background: (!hasPro || !settings.app_id || !settings.app_secret) ? '#ccc' : '#0078d4',
              cursor: (!hasPro || !settings.app_id || !settings.app_secret) ? 'not-allowed' : 'pointer',
            }}
          >
            Connect OneDrive
          </button>
        ) : (
          <div style={{ padding: '15px', background: '#d4edda', border: '1px solid #c3e6cb', borderRadius: '4px', maxWidth: '500px' }}>
            <p style={{ margin: '0 0 10px 0', color: '#155724', fontWeight: 600 }}>
              ✓ Connected to OneDrive
            </p>
            <button
              type="button"
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                if (setDisconnectIntegration && setShowDisconnectModal) {
                  setDisconnectIntegration('onedrive');
                  setShowDisconnectModal(true);
                }
              }}
              style={{
                padding: '8px 16px',
                background: '#dc3545',
                color: '#fff',
                border: 'none',
                borderRadius: '4px',
                fontSize: '14px',
                fontWeight: 500,
                cursor: 'pointer',
              }}
            >
              Disconnect OneDrive
            </button>
          </div>
        )}
      </div>
    </>
  );
}

